from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.colors import HexColor
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle
import os

OUT='output/pdf/Estrutura_Site_Luanne_Vieira_ANTT.pdf'
os.makedirs(os.path.dirname(OUT), exist_ok=True)
try:
    pdfmetrics.registerFont(TTFont('Arial', r'C:\Windows\Fonts\arial.ttf'))
    pdfmetrics.registerFont(TTFont('Arial-Bold', r'C:\Windows\Fonts\arialbd.ttf'))
    F,FB='Arial','Arial-Bold'
except:
    F,FB='Helvetica','Helvetica-Bold'
navy=HexColor('#102A43'); blue=HexColor('#176B87'); gold=HexColor('#C99A3A'); muted=HexColor('#52606D'); pale=HexColor('#F2F6F8')
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='T',fontName=FB,fontSize=25,leading=30,textColor=navy,spaceAfter=8))
s.add(ParagraphStyle(name='ST',fontName=FB,fontSize=14,leading=19,textColor=blue,spaceBefore=8,spaceAfter=5))
s.add(ParagraphStyle(name='D',fontName=F,fontSize=10.5,leading=16,textColor=HexColor('#243B53'),spaceAfter=9))
s.add(ParagraphStyle(name='Menu',fontName=FB,fontSize=9.5,leading=13,textColor=navy))
s.add(ParagraphStyle(name='Small',fontName=F,fontSize=8.5,leading=12,textColor=muted))
s.add(ParagraphStyle(name='Cover',fontName=FB,fontSize=29,leading=35,textColor=colors.white,spaceAfter=12))
s.add(ParagraphStyle(name='CoverD',fontName=F,fontSize=14,leading=20,textColor=HexColor('#D9EAF0')))
def p(x,style='D'): return Paragraph(x, s[style])
def menu(items):
    t=Table([[p(x,'Menu') for x in items]],colWidths=[(174*mm)/len(items)]*len(items))
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),pale),('BOX',(0,0),(-1,-1),0.6,HexColor('#D9E2EC')),('INNERGRID',(0,0),(-1,-1),0.3,HexColor('#D9E2EC')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]))
    return t
def hdr(c,doc):
    c.saveState(); w,h=A4; c.setStrokeColor(HexColor('#D9E2EC')); c.line(18*mm,h-15*mm,w-18*mm,h-15*mm); c.setFont(F,8); c.setFillColor(muted); c.drawString(18*mm,h-11*mm,'Luanne Vieira Advocacia | Estrutura do site'); c.drawRightString(w-18*mm,12*mm,str(doc.page)); c.restoreState()
def cover(c,doc):
    c.saveState(); w,h=A4; c.setFillColor(navy); c.rect(0,0,w,h,fill=1,stroke=0); c.setFillColor(blue); c.rect(0,h-45*mm,w,45*mm,fill=1,stroke=0); c.setFillColor(gold); c.rect(18*mm,h-48*mm,28*mm,3*mm,fill=1,stroke=0); c.restoreState()
story=[Spacer(1,30*mm),p('ESTRUTURA DO NOVO SITE','Small'),p('Luanne Vieira<br/>Assessoria Técnica e Jurídica em Transporte de Passageiros','Cover'),p('Copy organizada para visualização do site: menu, títulos, subtítulos e descrições.','CoverD'),Spacer(1,40*mm),p('Foco: empresas médias e grandes do transporte rodoviário intermunicipal e interestadual de passageiros.','CoverD'),PageBreak()]

story += [p('MENU PRINCIPAL','T'),menu(['Início','Atuação','Sobre Luanne','Radar Rodoviário','Contato']),Spacer(1,15),p('MENU ATUAÇÃO','ST'),menu(['Regularização','Fiscalização','Conformidade','Mercados']),Spacer(1,15),p('BOTÕES PRINCIPAIS','ST'),menu(['Falar com Luanne','Solicitar análise'])]
story += [PageBreak(),p('INÍCIO','T'),p('TÍTULO','Small'),p('Assessoria Técnica e Jurídica em Transporte de Passageiros.','T'),p('SUBTÍTULO','Small'),p('Atuação jurídica perante órgãos reguladores federais e estaduais, com visão técnica das exigências e da realidade operacional das empresas.','ST'),p('DESCRIÇÃO','Small'),p('Luanne Vieira atua pessoalmente na análise das demandas e na construção de estratégias jurídicas para empresas de transporte rodoviário intermunicipal e interestadual de passageiros.','D'),p('TÍTULO','Small'),p('A regulação pode impactar toda a operação.','ST'),p('DESCRIÇÃO','Small'),p('Uma decisão regulatória pode afetar mercados, linhas, investimentos, frota, contratos e a continuidade do serviço. Por isso, a atuação jurídica precisa compreender a operação da empresa e antecipar riscos perante os órgãos reguladores.','D'),p('TÍTULO','Small'),p('Atuação para empresas que não podem operar no improviso.','ST'),p('DESCRIÇÃO','Small'),p('Assessoria para empresas de transporte que buscam segurança técnica e jurídica para operar, crescer e responder às exigências regulatórias.','D'),p('BOTÃO','Small'),p('Falar com Luanne','ST')]
story += [PageBreak(),p('ATUAÇÃO','T'),p('TÍTULO','Small'),p('Soluções técnicas e jurídicas para a operação regulada.','T'),p('SUBTÍTULO','Small'),p('Da regularização à fiscalização, Luanne Vieira acompanha as principais demandas de empresas de transporte rodoviário intermunicipal e interestadual de passageiros perante órgãos reguladores federais e estaduais.','ST')]
for a,b in [('Regularização e autorizações','Habilitação, TAR, LOP, mercados, documentação e alterações operacionais para empresas que desejam operar ou expandir no transporte interestadual.'),('Fiscalização e defesa administrativa','Análise de autos de infração, notificações, defesas, recursos e processos que possam resultar em multas, suspensão ou cassação.'),('Conformidade regulatória','Diagnóstico preventivo da operação, revisão de documentos e orientação para reduzir vulnerabilidades perante a fiscalização.'),('Assessoria regulatória contínua','Acompanhamento de normas, comunicados, prazos e decisões que possam afetar a estratégia da empresa.'),('Mercados e expansão','Orientação em janelas, requerimentos, novos mercados e planejamento regulatório para crescimento seguro.')]:
    story += [p('TÍTULO','Small'),p(a,'ST'),p('DESCRIÇÃO','Small'),p(b.replace('transporte interestadual','transporte intermunicipal e interestadual'),'D')]
story += [PageBreak(),p('PÁGINA: REGULARIZAÇÃO E AUTORIZAÇÕES','T'),p('TÍTULO','Small'),p('Sua empresa preparada para operar e expandir.','T'),p('SUBTÍTULO','Small'),p('A regularidade documental e operacional é a base para uma atuação segura no transporte intermunicipal e interestadual de passageiros.','ST'),p('DESCRIÇÃO','Small'),p('Assessoria na análise de documentos, habilitação, autorizações, TAR, LOP, mercados e alterações operacionais aplicáveis à empresa perante os órgãos reguladores competentes.','D'),p('TÍTULO','Small'),p('Regularização com visão estratégica.','ST'),p('DESCRIÇÃO','Small'),p('Cada procedimento deve ser analisado considerando o tipo de serviço, a operação pretendida, os prazos e os riscos regulatórios envolvidos.','D'),p('BOTÃO','Small'),p('Conversar sobre regularização','ST'),p('PÁGINA: FISCALIZAÇÃO E DEFESA','T'),p('TÍTULO','Small'),p('Uma autuação exige análise e resposta técnica.','T'),p('SUBTÍTULO','Small'),p('Defesa administrativa para proteger a operação da sua empresa perante os órgãos reguladores.','ST'),p('DESCRIÇÃO','Small'),p('Análise de autos de infração, notificações, documentos, enquadramento e processo administrativo para definir a estratégia adequada de defesa, recurso ou manifestação.','D'),p('BOTÃO','Small'),p('Solicitar análise','ST')]
story += [PageBreak(),p('PÁGINA: CONFORMIDADE REGULATÓRIA','T'),p('TÍTULO','Small'),p('Prevenir riscos antes que eles interrompam a operação.','T'),p('SUBTÍTULO','Small'),p('A conformidade regulatória começa antes da fiscalização.','ST'),p('DESCRIÇÃO','Small'),p('O diagnóstico regulatório identifica inconsistências em documentos, autorizações, cadastros, operação e procedimentos internos, permitindo que a empresa corrija vulnerabilidades com planejamento.','D'),p('TÍTULO','Small'),p('Mais segurança para decisões operacionais.','ST'),p('DESCRIÇÃO','Small'),p('A orientação técnica e jurídica considera a realidade da empresa e traduz a complexidade da regulação em decisões mais claras para gestores e responsáveis pela operação.','D'),p('PÁGINA: MERCADOS E EXPANSÃO','T'),p('TÍTULO','Small'),p('Crescer no transporte de passageiros exige planejamento regulatório.','T'),p('SUBTÍTULO','Small'),p('Novos mercados, requerimentos e alterações operacionais precisam ser avaliados com antecedência perante os órgãos federais e estaduais.','ST'),p('DESCRIÇÃO','Small'),p('Assessoria para empresas que desejam expandir sua operação intermunicipal e interestadual com atenção a documentos, prazos, requisitos e possíveis impactos regulatórios.','D')]
story += [PageBreak(),p('SOBRE LUANNE','T'),p('TÍTULO','Small'),p('Conhecimento técnico com atuação pessoal e estratégica.','T'),p('SUBTÍTULO','Small'),p('Luanne Vieira é advogada com 9 anos de experiência na área e atuação voltada à regulação do transporte rodoviário intermunicipal e interestadual de passageiros.','ST'),p('DESCRIÇÃO','Small'),p('Seu trabalho é direcionado a empresas médias e grandes que precisam lidar com a complexidade dos órgãos reguladores com mais segurança, clareza e planejamento.','D'),p('DESCRIÇÃO','Small'),p('A atuação é pessoal. Cada demanda é analisada de perto, considerando o contexto da empresa, os riscos envolvidos e os objetivos da operação.','D'),p('DESCRIÇÃO','Small'),p('O objetivo é construir estratégias técnicas e jurídicas que ajudem a empresa a preservar sua operação, cumprir as exigências regulatórias e tomar decisões melhores diante de um ambiente em constante transformação.','D'),p('TÍTULO','Small'),p('Atendimento em todo o Brasil.','ST'),p('DESCRIÇÃO','Small'),p('Atuação remota e estratégica para empresas de transporte localizadas em diferentes regiões do país.','D'),p('PÁGINA: RADAR RODOVIÁRIO','T'),p('TÍTULO','Small'),p('Informação regulatória para decisões mais seguras.','T'),p('SUBTÍTULO','Small'),p('Análises sobre normas, fiscalização, autorizações, mercados e mudanças que afetam o transporte rodoviário de passageiros nos âmbitos federal e estadual.','ST'),p('BOTÃO','Small'),p('Acessar o Radar Rodoviário','ST')]
story += [PageBreak(),p('CONTATO','T'),p('TÍTULO','Small'),p('Vamos entender o cenário regulatório da sua empresa?','T'),p('SUBTÍTULO','Small'),p('Envie uma breve descrição da sua demanda para iniciar uma conversa com Luanne Vieira.','ST'),p('DESCRIÇÃO','Small'),p('O atendimento é direcionado a empresas médias e grandes do transporte rodoviário intermunicipal e interestadual de passageiros que precisam de orientação em regularização, fiscalização, defesa ou conformidade regulatória.','D'),p('TÍTULO','Small'),p('Fale sobre a sua empresa.','ST'),p('DESCRIÇÃO','Small'),p('Explique o momento atual da operação, o principal desafio e como podemos ajudar.','D'),p('CAMPOS DO FORMULÁRIO','Small'),menu(['Nome','Empresa','Cargo','E-mail corporativo']),Spacer(1,8),menu(['Telefone/WhatsApp','Tipo de demanda','Mensagem']),Spacer(1,10),p('BOTÃO','Small'),p('Solicitar contato','ST')]

doc=SimpleDocTemplate(OUT,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=22*mm,bottomMargin=18*mm,title='Estrutura do site Luanne Vieira Advocacia ANTT')
